  .me99-list-item i {
   font-size: 16px;
   margin-top: 2px;
   flex-shrink: 0;
  }

  .me99-card:nth-of-type(1) .me99-list-item i {
   color: var(--safety-orange);
  }

  .me99-example-box {
   background: #FFF9F5;
   border-left: 3px solid var(--safety-orange);
   padding: 12px 14px;
   border-radius: 0 12px 12px 0;
   margin-top: 4px;
   font-size: 12px;
   font-weight: 600;
   color: #444;
   line-height: 1.6;
  }

