   border-radius: 16px;
   margin-top: 24px;
   padding: 4px;
  }

  .me99-status-row {
   display: flex;
   align-items: center;
   gap: 14px;
   padding: 12px 14px;
   font-size: 13px;
   font-weight: 800;
   color: var(--navy-dark);
   background: #FFFFFF;
   border-radius: 12px;
   margin-bottom: 4px;
   box-shadow: 0 2px 8px rgba(0, 0, 0, 0.02);
  }

