   color: #10B981;
   font-size: 20px;
   filter: drop-shadow(0 2px 4px rgba(16, 185, 129, 0.3));
  }

  .me99-status-row i.fa-circle-xmark {
   color: #EF4444;
   font-size: 20px;
   filter: drop-shadow(0 2px 4px rgba(239, 68, 68, 0.3));
  }

