   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 16px;
   position: relative;
   z-index: 2;
  }

  .me99-action-box {
   text-align: center;
   display: flex;
   flex-direction: column;
   gap: 10px;
   text-decoration: none;
   background: var(--bg-card);
   border-radius: 20px;
   padding: 16px 12px;
   box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
   position: relative;
   overflow: hidden;
  }

