   content: '';
   position: absolute;
   top: 0;
   left: -100%;
   width: 50%;
   height: 100%;
   background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.8), transparent);
   transform: skewX(-20deg);
   animation: shimmer 3s infinite;
  }

  @keyframes shimmer {
   0% {
    left: -100%;
   }

   20% {
    left: 200%;
   }

   100% {
    left: 200%;
   }
  }

  .me99-action-label {
   font-size: 11px;
   font-weight: 900;
   color: var(--text-muted);
   text-transform: uppercase;
   letter-spacing: 0.5px;
  }

